<?php
declare(strict_types=1);

final class MigrationQuarantineReadModel
{
    public const PAGE_SIZE=25;
    public function __construct(private mysqli$db,private string$prefix){if(preg_match('/^[A-Za-z0-9_]+$/D',$prefix)!==1)throw new InvalidArgumentException('Invalid prefix');}
    public function read(array$filters,int$page):array
    {
        $page=max(1,$page);$category=in_array($filters['category']??'',['native_candidate','legacy_active','legacy_historical'],true)?(string)$filters['category']:'';$code=preg_match('/^[A-Z0-9_]{1,100}$/D',(string)($filters['code']??''))===1?(string)$filters['code']:'';
        if(!$this->exists('fm2_migration_quarantine_registry')||!$this->exists('fm2_migration_quarantine_observations'))return['rows'=>[],'total'=>0,'page'=>1,'pages'=>1,'codes'=>[]];
        $where=[];$types='';$args=[];if($category!==''){$where[]='q.category=?';$types.='s';$args[]=$category;}if($code!==''){$where[]='JSON_CONTAINS(q.quarantine_codes_json,JSON_QUOTE(?))';$types.='s';$args[]=$code;}$sqlWhere=$where===[]?'':' WHERE '.implode(' AND ',$where);
        $count=$this->prepare("SELECT COUNT(*) n FROM `{$this->prefix}fm2_migration_quarantine_registry` q{$sqlWhere}",$types,$args)->get_result()->fetch_assoc();$total=(int)($count['n']??0);$pages=max(1,(int)ceil($total/self::PAGE_SIZE));$page=min($page,$pages);$offset=($page-1)*self::PAGE_SIZE;
        $sql="SELECT q.source_locator,q.source_cutoff_at,q.source_digest,q.classification_version,q.category,q.reason_codes_json,q.quarantine_codes_json,q.first_seen_at,COUNT(o.id) observation_count,MAX(o.observed_at) last_observed_at,MAX(o.run_id) last_run_id FROM `{$this->prefix}fm2_migration_quarantine_registry` q LEFT JOIN `{$this->prefix}fm2_migration_quarantine_observations` o ON o.registry_id=q.id{$sqlWhere} GROUP BY q.id ORDER BY q.source_locator ASC LIMIT ".self::PAGE_SIZE." OFFSET {$offset}";$rows=[];foreach($this->prepare($sql,$types,$args)->get_result()->fetch_all(MYSQLI_ASSOC)as$r){$reasons=$this->codes($r['reason_codes_json']);$quarantine=$this->codes($r['quarantine_codes_json']);$locator=(string)$r['source_locator'];$digest=(string)$r['source_digest'];$run=(string)($r['last_run_id']??'');$rows[]=['reference'=>'Q-'.strtoupper(substr(hash('sha256',$locator.'|'.$digest),0,12)),'sourceLocator'=>$locator,'category'=>(string)$r['category'],'classificationVersion'=>(string)$r['classification_version'],'reasonCodes'=>$reasons,'quarantineCodes'=>$quarantine,'sourceCutoffAt'=>(string)$r['source_cutoff_at'],'sourceDigest'=>$digest,'locatorHash'=>str_starts_with($locator,'hmac-sha256:')?substr($locator,12):hash('sha256',$locator),'firstSeenAt'=>(string)$r['first_seen_at'],'lastObservedAt'=>(string)($r['last_observed_at']??''),'observationCount'=>(int)$r['observation_count'],'runReference'=>$run===''?'':'RUN-'.strtoupper(substr(hash('sha256',$run),0,10)),'status'=>(int)$r['observation_count']>0?'observed':'registered'];}
        $codes=[];foreach($this->db->query("SELECT quarantine_codes_json FROM `{$this->prefix}fm2_migration_quarantine_registry` ORDER BY id LIMIT 500")->fetch_all(MYSQLI_ASSOC)as$r)foreach($this->codes($r['quarantine_codes_json'])as$c)$codes[$c]=true;$codes=array_keys($codes);sort($codes,SORT_STRING);return['rows'=>$rows,'total'=>$total,'page'=>$page,'pages'=>$pages,'codes'=>$codes,'filters'=>['category'=>$category,'code'=>$code]];
    }
    private function exists(string$suffix):bool{$name=$this->prefix.$suffix;$s=$this->db->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$s->bind_param('s',$name);$s->execute();return$s->get_result()->fetch_assoc()!==null;}
    private function prepare(string$sql,string$types,array$args):mysqli_stmt{$s=$this->db->prepare($sql);if($types!=='')$s->bind_param($types,...$args);$s->execute();return$s;}
    private function codes(mixed$json):array{$v=json_decode((string)$json,true);if(!is_array($v))throw new RuntimeException('Invalid quarantine registry JSON');$v=array_values(array_unique(array_map('strval',$v)));sort($v,SORT_STRING);return$v;}
}
